/* Bounded LZ4 block decoder for immutable UI assets generated by tools/lz4blk.py.
 * The caller supplies short-lived stack storage; neither audio nor DMA sees it. */
#pragma once
static int asset_lz4(const uint8_t *src, uint32_t n, uint8_t *dst, uint32_t cap)
{
    uint32_t i = 0, o = 0;
    while (i < n) {
        uint32_t token = src[i++], len = token >> 4, off, k;
        if (len == 15u) {
            do { if (i >= n) return 0; k = src[i++]; if (k > cap || len > cap - k) return 0; len += k; } while (k == 255u);
        }
        if (len > n - i || len > cap - o) return 0;
        while (len--) dst[o++] = src[i++];
        if (i == n) return o == cap;
        if (n - i < 2u) return 0;
        off = src[i] | (uint32_t)src[i + 1u] << 8; i += 2u;
        if (!off || off > o) return 0;
        len = (token & 15u) + 4u;
        if (len == 19u) {
            do { if (i >= n) return 0; k = src[i++]; if (k > cap || len > cap - k) return 0; len += k; } while (k == 255u);
        }
        if (len > cap - o) return 0;
        while (len--) { dst[o] = dst[o - off]; o++; }
    }
    return o == cap;
}
